<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('programme_manager');require_once __DIR__.'/_management_suite_helpers.php';
$user=current_user();$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);if($managerId<=0){http_response_code(403);exit('Invalid Programme Manager account.');}
$currentPage='budget_performance';$pageTitle='Budget Performance & Cost Monitoring';$budgetReady=pm_table_exists($conn,'programme_budgets');$expenseReady=pm_table_exists($conn,'programme_expenditures');$rows=[];$allocated=0.0;$spent=0.0;$over=0;$util=0.0;
if($budgetReady&&$expenseReady){$s=$conn->prepare('SELECT b.programme_id,b.cohort_id,GROUP_CONCAT(DISTINCT b.fiscal_period ORDER BY b.fiscal_period SEPARATOR ', ') fiscal_period,SUM(b.allocated_amount) allocated_amount,p.name programme_name,c.name cohort_name,COALESCE((SELECT SUM(x.amount) FROM programme_expenditures x WHERE x.programme_id=b.programme_id AND (x.cohort_id <=> b.cohort_id)),0) actual_spending FROM programme_budgets b JOIN programmes p ON p.id=b.programme_id LEFT JOIN cohorts c ON c.id=b.cohort_id WHERE p.programme_manager_id=? GROUP BY b.programme_id,b.cohort_id,p.name,c.name ORDER BY p.name,c.name');if($s){$s->bind_param('i',$managerId);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}foreach($rows as $r){$a=(float)$r['allocated_amount'];$x=(float)$r['actual_spending'];$allocated+=$a;$spent+=$x;if($x>$a)$over++;}}
$remaining=$allocated-$spent;$util=$allocated>0?($spent/$allocated)*100:0;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($pageTitle)?></title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?=url('css/styles.css')?>"><link rel="stylesheet" href="<?=url('css/programme_manager_enhancements.css')?>"><link rel="stylesheet" href="<?=url('css/programme_management_suite.css')?>"></head><body class="dashboard-page"><div class="dashboard"><?php require __DIR__.'/sidebar.php';?><main class="dashboard__main"><?php require __DIR__.'/navbar.php';?><div class="pm-suite"><?=render_flashes()?><section class="pm-suite-hero"><div><span class="pm-suite-eyebrow">Financial control</span><h1>Budget Performance &amp; Cost Monitoring</h1><p>Compare approved programme and cohort allocations with recorded operational expenditure. This view reuses the existing budget and expenditure ledger to avoid duplicate financial records.</p></div><a class="pm-suite-btn" href="<?=url('programme/budgets.php')?>">Manage budgets &amp; expenses</a></section><?php if(!$budgetReady||!$expenseReady):?><div class="pm-suite-notice">The existing financial tables are not available. Import <code>database/programme_management_suite.sql</code> first.</div><?php endif;?>
<section class="pm-suite-kpis"><article class="pm-suite-kpi"><small>Allocated budget</small><strong>R <?=number_format($allocated,2)?></strong><span>Existing budget allocations</span></article><article class="pm-suite-kpi"><small>Actual expenditure</small><strong>R <?=number_format($spent,2)?></strong><span>Recorded operational spending</span></article><article class="pm-suite-kpi"><small>Budget variance</small><strong>R <?=number_format($remaining,2)?></strong><span><?=$remaining<0?'Overspent':'Remaining allocation'?></span></article><article class="pm-suite-kpi"><small>Budget utilisation</small><strong><?=number_format($util,1)?>%</strong><span>Actual expenditure ÷ allocation</span></article></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Budget performance by programme and cohort</h2><p>Actual spending is matched to the same programme and cohort as each allocation.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Programme / cohort</th><th>Period</th><th>Allocated</th><th>Actual spending</th><th>Variance</th><th>Performance</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="pm-suite-empty">No budget allocations found. Add allocations on the Budget &amp; Expenditure page.</td></tr><?php else:foreach($rows as $r):$a=(float)$r['allocated_amount'];$x=(float)$r['actual_spending'];$v=$a-$x;$pct=$a>0?($x/$a)*100:0;?><tr><td><strong><?=e($r['programme_name'])?></strong><span class="pm-suite-muted"><?=e($r['cohort_name']?:'Programme-wide')?></span></td><td><?=e($r['fiscal_period'])?></td><td>R <?=number_format($a,2)?></td><td>R <?=number_format($x,2)?></td><td><strong>R <?=number_format($v,2)?></strong></td><td><span class="pm-suite-pill <?=$v<0?'bad':($pct>=85?'warn':'good')?>"><?=$v<0?'Overspending':($pct>=85?'Near limit':'Within budget')?></span><span class="pm-suite-muted"><?=number_format($pct,1)?>% utilised</span></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<div class="pm-suite-notice">Financial accuracy note: allocations are compared against expenditure recorded for the matching programme/cohort. If multiple budget periods exist for the same programme/cohort, confirm that the expenditure ledger is period-tagged before interpreting each period row separately; the current schema does not associate an expense with a fiscal period.</div></div></main></div><script src="<?=url('js/programme_manager_enhancements.js')?>"></script><script src="<?=url('js/original_pm_sidebar.js')?>"></script></body></html>
